  /* ---------- Seite Finanzieren vs. Bar (/finance-vs-cash) ---------- */
  "fvc_title": "Rechner Finanzieren vs. Bar Bezahlen — Sollten Sie Finanzieren oder Bar Kaufen? 2026",
  "fvc_description": "Vergleichen Sie die tatsächlichen Kosten einer Finanzierung gegenüber einem Barkauf. Kostenloser Rechner mit Opportunitätskosten, Gesamtzinsen und investiertem Kapital im Zeitverlauf.",
  "fvc_subtitle": "Sehen Sie die tatsächlichen Kosten der Finanzierung eines Hauses gegenüber dem Barkauf — einschließlich dessen, was Ihr Geld hätte verdienen können, wenn es stattdessen investiert worden wäre.",
  "fvc_form_title": "Eingaben Finanzierung vs. Bar",
  "fvc_input_price": "Hauspreis",
  "fvc_input_down": "Anzahlung (%)",
