  "pts_title": "Discount Points Rechner — Sollten Sie Hypothekenpunkte Kaufen?",
  "pts_description": "Kostenloser Discount-Points-Rechner. Sehen Sie, wie viele Monate es dauert, bis sich Hypothekenpunkte bezahlt machen. Vergleichen Sie 0, 1, 2 und 3 Punkte mit Break-Even-Analyse.",
  "pts_subtitle": "Sehen Sie, wie viele Monate es dauert, bis sich Hypotheken-Discount-Points bezahlt machen, und ob ein Zinskauf finanziell sinnvoll ist.",
  "pts_form_title": "Kreditdetails",
  "pts_input_loan": "Kreditbetrag ($)",
  "pts_input_rate": "Grundzinssatz (%)",
  "pts_input_term": "Kreditlaufzeit (Jahre)",
  "pts_points_title": "Punkte-Einstellungen",
  "pts_input_count": "Anzahl der Punkte",
  "pts_hint_count": "Jeder Punkt kostet 1 % des Kreditbetrags und reduziert den Zinssatz typischerweise um ~0,25 %.",
